function pcw_bp_link($text, $href, $kind='primary') {
    return '<a class="pcw-btn pcw-'.$kind.'" data-funnel href="'.esc_url($href).'">'.esc_html($text).' <span aria-hidden="true">&#8599;</span></a>';
}

function pcw_bp_image($cfg, $raw=false) {
    $images = array(
        'chirogoaz' => 'data:image/png;base64,',
        'aromahmt' => 'data:image/jpeg;base64,',
        'renew48' => 'data:image/jpeg;base64,'
    );
    $alts = array(
        'chirogoaz' => 'ChiroGoAZ brand mark',
        'aromahmt' => 'AromaTouch wellness treatment',
        'renew48' => 'Renew48 provider portrait'
    );
    if ($cfg['domain'] === 'chirogoaz') { $src = content_url('uploads/pcw-approved/logo-chirogoaz.png'); } elseif ($cfg['domain'] === 'aromahmt') { $src = content_url('uploads/pcw-approved/aromatouch.jpg'); } else { $src = content_url('uploads/pcw-approved/casey-headshot.jpg'); }
    $alt = $alts[$cfg['domain']] ?? $alts['renew48'];
    $image_src = $raw ? $src : 'pcw-bp-image-token';
    return '<figure class="pcw-hero-media"><img src="' . esc_attr($image_src) . '" alt="' . esc_attr($alt) . '" loading="eager" decoding="async"></figure>';
}

add_filter('the_content', function ($content) {
    if (strpos($content, 'pcw-bp-image-token') === false) { return $content; }
    $raw = pcw_bp_image(pcw_bp_config(), true);
    if (preg_match('/src="([^"]+)"/', $raw, $match)) {
        $content = str_replace('pcw-bp-image-token', $match[1], $content);
    }
    return $content;
}, 20);

function pcw_bp_visual_strip($cfg) {
    return '<section class="pcw-visual-strip"><div class="pcw-visual-copy"><span class="pcw-kicker">A considered next step</span><h2>Care should feel clear before it begins.</h2><p>Explore the people, rituals, and pathways that make this domain yours.</p></div>'.pcw_bp_image($cfg).'</section>';
}

function pcw_bp_visual_mosaic($cfg) {
