function pcw_bp_layout($cfg, $kicker, $title, $intro, $inner) {
    $jane = $cfg['jane'] ? pcw_bp_link('Open Jane to book', $cfg['jane'], 'primary') : pcw_bp_link('Start a conversation', home_url('/contact/'), 'primary');
    return '<div class="pcw-bp pcw-'.$cfg['mode'].'"><section class="pcw-hero"><div class="pcw-hero-copy"><span class="pcw-kicker">'.esc_html($kicker).'</span><h1>'.esc_html($title).'</h1><p>'.esc_html($intro).'</p><div class="pcw-actions">'.$jane.' '.pcw_bp_link('Explore memberships', home_url('/memberships/'), 'quiet').'</div></div><div class="pcw-orbit" aria-hidden="true">'.pcw_bp_image($cfg).'<span></span><span></span><span></span></div></section>'.pcw_bp_visual_mosaic($cfg).$inner.'</div>';
}

