er;border-radius:36px;background:linear-gradient(110deg,#ffffffb8,#ffffff45);border:1px solid #ffffffc8;box-shadow:0 24px 60px #203b3624;overflow:hidden}.pcw-visual-strip .pcw-hero-media{position:relative;inset:auto;transform:rotate(-3deg);min-height:260px}.pcw-visual-strip .pcw-hero-media img{max-height:300px}.pcw-visual-copy h2{font-size:clamp(34px,4vw,62px);margin:10px 0 18px;color:var(--primary)}.pcw-visual-copy p{max-width:480px;color:var(--muted);line-height:1.7}@media(max-width:620px){.pcw-visual-strip{width:88vw;margin-bottom:70px;padding:24px;grid-template-columns:1fr}.pcw-visual-strip .pcw-hero-media{min-height:220px}}.pcw-hero-media{position:absolute;inset:10% 8% 10% 8%;z-index:1;margin:0;display:grid;place-items:center;transform:rotate(4deg)}.pcw-hero-media img{display:block;width:min(100%,420px);max-height:390px;object-fit:contain;border-radius:34px;border:1px solid #ffffffb8;box-shadow:18px 24px 70px #203b3640;background:#fff9;padding:10px}.pcw-aroma .pcw-hero-media img,.pcw-cobranded .pcw-hero-media img{object-fit:cover;aspect-ratio:1}.pcw-chiro .pcw-hero-media img{background:transparent;border:0;box-shadow:none;padding:0}@media(max-width:620px){.pcw-hero-media{inset:5% 4% 5% 4%}.pcw-hero-media img{max-height:270px;border-radius:26px}}#masthead,#colophon,#comments,.comments-area,.site-header,.entry-header,.page-header,.ast-header-break-point .main-header-bar,.ast-primary-header-bar,.ast-main-header-wrap,.main-header-bar,.ast-footer-wrap,.elementor-location-header,.elementor-location-footer,.sharedaddy,.sd-content,.jp-sharing-input-copy{display:none!important}.pcw-chrome{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 5vw;border-bottom:1px solid #203b3630;background:#fffaf1;position:relative;z-index:20;font-family:Raleway,Quicksand,system-ui,sans-serif}.pcw-floating-head{position:fixed!important;top:0;left:0;right:0;z-index:9999}.pcw-site-footer{margin-top:0;border-top:1px solid #203b3630}.pcw-chrome-brand{font-family:Quicksand,Raleway,sans-serif;font-weight:800;letter-spacing:-.03em;color:#203b36;text-decoration:none}.pcw-chrome-nav{display:flex;gap:18px;align-items:center;flex-wrap:wrap}.pcw-chrome-nav a{color:#203b36;text-decoration:none;font-size:13px;font-weight:700}.pcw-chrome-nav a:last-child{padding:10px 16px;border-radius:999px;background:#b95c43;color:#fff}.pcw-chrome-menu{display:none;border:0;background:transparent;color:#203b36;font:inherit;font-weight:800;padding:8px 0;cursor:pointer}.pcw-chrome-menu:focus-visible,.pcw-chrome-nav a:focus-visible,.pcw-btn:focus-visible{outline:3px solid var(--accent,#b95c43);outline-offset:4px}.pcw-chrome-nav.is-open{display:flex}@media(max-width:700px){.pcw-chrome{padding:16px 6vw}.pcw-chrome-menu{display:block}.pcw-chrome-nav{display:none;width:100%;padding-top:12px}.pcw-chrome{flex-wrap:wrap}.pcw-chrome-nav.is-open{display:grid;gap:12px}.pcw-chrome-nav a:last-child{display:inline-flex;width:max-content}}.pcw-bp{--ink:#203b36;--muted:#65736d;--cream:#fffaf1;--line:#ffffffb8;--accent:#b95c43;--primary:#314b68;font-family:Raleway,Quicksand,system-ui,sans-serif;color:var(--ink);background:linear-gradient(145deg,#f7eee1,#e6eee9 68%,#f0d4c0);padding:0 0 1px}.pcw-bp *{box-sizing:border-box}.pcw-bp a{text-decoration:none}.pcw-bp h1,.pcw-bp h2,.pcw-bp h3{font-family:Quicksand,Raleway,sans-serif;line-height:1.02;letter-spacing:-.045em}.pcw-hero{min-height:560px;display:grid;grid-template-columns:minmax(0,1.08fr) minmax(280px,.92fr);gap:7%;align-items:center;padding:clamp(60px,9vw,120px) 7%;position:relative;overflow:hidden}.pcw-home-hero{min-height:720px}.pcw-hero-copy{position:relative;z-index:2;max-width:720px}.pcw-kicker{display:block;text-transform:uppercase;letter-spacing:.18em;font-size:11px;font-weight:800;color:var(--accent);margin-bottom:16px}.pcw-hero h1{font-size:clamp(52px,8vw,106px);margin:0 0 24px;color:var(--primary)}.pcw-hero p{font-size:18px;line-height:1.7;max-width:580px;color:var(--muted)}.pcw-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:30px}.pcw-btn{display:inline-flex;align-items:center;gap:12px;padding:14px 20px;border-radius:999px;font-weight:800;font-size:13px;transition:transform .2s ease,box-shadow .2s ease}.pcw-btn:hover,.pcw-btn:focus-visible{transform:translateY(-2px);box-shadow:0 14px 24px #203b3630}.pcw-primary{background:var(--accent);color:white}.pcw-quiet{border:1px solid #203b3650;background:#ffffff70;color:var(--primary)}.pcw-text{padding:0;color:var(--primary);border-radius:0}.pcw-orbit{min-height:390px;position:relative;display:grid;place-items:center}.pcw-orbit:before{content:"";position:absolute;width:92%;aspect-ratio:1;border-radius:48% 52% 40% 60%;border:1px solid #ffffffc8;transform:rotate(-12deg);box-shadow:25px 30px 70px #45534d30;background:radial-gradient(circle at 35% 25%,#fff9 0 7%,transparent 24%),linear-gradient(145deg,#e6b36b,#879d91 65%,#314b68)}.pcw-orbit span{position:absolute;border:1px solid #fff9;border-radius:50%;width:58%;aspect-ratio:1;transform:rotate(28deg)}.pcw-orbit span:nth-child(2){width:74%;transform:rotate(-38deg)}.pcw-orbit span:nth-child(3){width:43%;transform:rotate(72deg)}.pcw-orbit b{position:relative;z-index:1;text-align:center;color:white;font-size:22px;letter-spacing:.05em}.pcw-section,.pcw-split,.pcw-editorial,.pcw-contact-band,.pcw-feature,.pcw-note{width:min(1180px,86vw);margin:0 auto;padding:100px 0}.pcw-section-head{display:flex;justify-content:space-between;gap:30px;align-items:end;margin-bottom:36px}.pcw-section-head h2,.pcw-feature h2,.pcw-contact-band h2{font-size:clamp(38px,5vw,70px);max-width:720px;margin:0}.pcw-section-head p{max-width:390px;color:var(--muted);line-height:1.7}.pcw-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.pcw-card{min-height:245px;padding:28px;border-radius:28px;background:#fff9;border:1px solid var(--line);box-shadow:0 20px 50px #45534d1c;display:flex;flex-direction:column;justify-content:space-between}.pcw-card:nth-child(2){transform:translateY(24px);background:#d7e4dbb8}.pcw-card:nth-child(3){transform:translateY(-14px);background:#efd2c0c0}.pcw-card h2,.pcw-card h3{font-size:29px;margin:12px 0}.pcw-card p,.pcw-path p,.pcw-detail p{color:var(--muted);line-height:1.7}.pcw-index{font-size:12px;color:var(--accent);font-weight:800;letter-spacing:.14em}.pcw-split,.pcw-editorial{display:grid;grid-template-columns:1fr 1fr;gap:18px}.pcw-split article,.pcw-editorial article,.pcw-detail>div,.pcw-detail>aside{padding:44px;border-radius:32px;background:#fff9;box-shadow:0 22px 55px #45534d1b;min-height:300px}.pcw-split article:nth-child(1){background:linear-gradient(145deg,#314b68,#6e8593);color:white}.pcw-split article:nth-child(1) p{color:#e5edf0}.pcw-split article:nth-child(2){background:linear-gradient(145deg,#d9bf98,#a8c3ae)}.pcw-split h2,.pcw-editorial h2{font-size:clamp(36px,4vw,60px);margin:12px 0 18px}.pcw-paths{background:#314b68;color:white;width:100%;padding-left:7%;padding-right:7%;max-width:none}.pcw-paths .pcw-section-head p{color:#dbe4e7}.pcw-path-grid{grid-template-columns:repeat(4,1fr)}.pcw-path{min-height:220px;padding:27px;border-radius:25px;border:1px solid #ffffff40;background:#ffffff10}.pcw-path:nth-child(2){transform:translateY(20px);background:#d2a34a2c}.pcw-path:nth-child(3){transform:translateY(-12px);background:#e6a67a28}.pcw-path:nth-child(4){transform:translateY(28px);background:#d9e5dc1f}.pcw-path span{font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:#f2ca76;font-weight:800}.pcw-path h2,.pcw-path h3{font-size:31px;margin:30px 0 12px}.pcw-path p{color:#dbe4e7}.pcw-path strong{font-size:12px}.pcw-detail{display:grid;grid-template-columns:1.1fr .9fr;gap:18px;width:min(1180px,86vw);margin:auto;padding:90px 0}.pcw-detail ul{padding-left:20px;line-height:2}.pcw-steps{display:grid;gap:15px;padding:0;margin:22px 0 0;list-style:none}.pcw-steps li{display:grid;grid-template-columns:135px 1fr;gap:14px;align-items:start;padding:15px 0;border-top:1px solid #203b3630}.pcw-steps strong{color:var(--accent);font-size:11px;letter-spacing:.1em;text-transform:uppercase}.pcw-steps span{color:var(--muted);line-height:1.5}@media(max-width:620px){.pcw-steps li{grid-template-columns:1fr;gap:5px}}.pcw-note{border-left:4px solid var(--accent);padding:20px 24px;margin-bottom:80px;background:#fff9;line-height:1.7}.pcw-contact-band{display:flex;justify-content:space-between;gap:30px;align-items:center}.pcw-empty{min-height:70vh;display:grid;place-items:center;text-align:center;padding:100px 7%}.pcw-empty h1{font-size:clamp(48px,8vw,100px);color:var(--primary)}.pcw-chiro{--primary:#263d5a;--accent:#d68b49;background:linear-gradient(145deg,#ecf0f2,#dae5e7 55%,#edd2bb)}.pcw-aroma{--primary:#304b43;--accent:#b9684e;background:linear-gradient(145deg,#fbf5e9,#dce8dc 58%,#efd2bc)}.pcw-cobranded{--primary:#314b68;--accent:#b95c43}@media(max-width:900px){.pcw-hero,.pcw-detail{grid-template-columns:1fr}.pcw-grid{grid-template-columns:repeat(2,1fr)}.pcw-path-grid{grid-template-columns:repeat(2,1fr)}.pcw-section-head,.pcw-contact-band{display:block}.pcw-contact-band .pcw-actions{margin-top:25px}}@media(max-width:620px){.pcw-chrome{padding:16px 6vw}.pcw-chrome-nav{display:none}.pcw-chrome-menu{display:inline-flex;color:#203b36;font-size:12px;font-weight:800}.pcw-hero{padding:64px 6%;min-height:0}.pcw-home-hero{min-height:680px}.pcw-orbit{min-height:290px}.pcw-section,.pcw-split,.pcw-editorial,.pcw-detail,.pcw-contact-band,.pcw-feature{width:88vw;padding:70px 0;grid-template-columns:1fr}.pcw-grid,.pcw-path-grid{grid-template-columns:1fr}.pcw-card:nth-child(2),.pcw-card:nth-child(3),.pcw-path:nth-child(2),.pcw-path:nth-child(3),.pcw-path:nth-child(4){transform:none}.pcw-split article,.pcw-editorial article,.pcw-detail>div,.pcw-detail>aside{padding:30px}.pcw-section-head h2,.pcw-feature h2,.pcw-contact-band h2{font-size:44px}}@media(prefers-reduced-motion:reduce){.pcw-btn{transition:none}.pcw-btn:hover,.pcw-btn:focus-visible{transform:none}}${css}</style>';
}

