    $c=pcw_bp_config();
    echo '<nav class="pcw-chrome" aria-label="Primary navigation"><a class="pcw-chrome-brand" href="'.esc_url(home_url('/')).'">'.esc_html($c['name']).'</a><div id="pcw-primary-nav" class="pcw-chrome-nav"><a href="'.esc_url(home_url('/'.$c['service_slug'].'/')).'">Services</a><a href="'.esc_url(home_url('/memberships/')).'">Memberships</a><a href="'.esc_url(home_url('/blog/')).'">Journal</a><a href="'.esc_url(home_url('/shop/')).'">Shop</a><a href="'.esc_url(home_url('/about/')).'">About</a><a href="'.esc_url(home_url('/booking/')).'">Book</a></div><button class="pcw-chrome-menu" type="button" aria-expanded="false" aria-controls="pcw-primary-nav">Menu</button></nav>';
}
